async function submitContact( input: z.infer<typeof contactSchema> ): Promise<ActionResult> { const parsed = contactSchema.safeParse(input); if (!parsed.success) { return { ok: false, error: parsed.error.issues[0]?.message ?? "Invalid input" }; } if (await rateLimited()) { return { ok: false, error: "Too many submissions — please try again in a minute." }; } const { name, email, topic, subject, message } = parsed.data; const t = CONTACT_TOPICS[topic]; return deliver( `[${t.label}] ${subject || "New message"} — ${name}`, `New contact form submission from hubcharge.com

` + `Topic: ${t.label} (target response: ${t.sla})
` + `Name: ${name}
Email: ${email}
Subject: ${subject || "(none)"}

${message}` ); }

async function notifyMe( input: z.infer<typeof notifySchema> ): Promise<ActionResult> { const parsed = notifySchema.safeParse(input); if (!parsed.success) { return { ok: false, error: parsed.error.issues[0]?.message ?? "Invalid email" }; } if (await rateLimited()) { return { ok: false, error: "Too many submissions — please try again in a minute." }; } return deliver( "[Website] New-location notification request", `Someone asked to be notified about upcoming locations.

Email: ${parsed.data.email}
Interested in: ${parsed.data.location || "(any)"}` ); }

async function submitFeedback( input: z.infer<typeof feedbackSchema> ): Promise<ActionResult> { const parsed = feedbackSchema.safeParse(input); if (!parsed.success) { return { ok: false, error: "Invalid submission" }; } if (await rateLimited()) { return { ok: false, error: "Too many submissions — please try again in a minute." }; } const { options, message } = parsed.data; if (options.length === 0 && !message) { return { ok: false, error: "Pick an option or write a note first." }; } return deliver( "[Website] Nearby-services feedback", `Feedback from the site widget ("What do you want near HubCharge?")

Selected: ${options.join(", ") || "(none)"}
Message: ${message || "(none)"}` ); }

"""Re-derive every geometric claim in the covers from the shipped source.""" import re, math, pathlib, subprocess, json, sys src = pathlib.Path("components/guide-cover.tsx").read_text() FLOOR = int(re.search(r"const FLOOR = (\d+)", src)[1]) fails = [] # 1. every guide-backed cover names the idea it draws, and its guide really # says that. This is the check that stops a cover drifting from its page — # `milestones` was three numbered dots and `paperwork` led with a currency # mark on a page whose first heading is "Why this page has no dollar # amounts on it". content = pathlib.Path("lib/guide-content.tsx").read_text() slugpage = pathlib.Path("app/charging-101/[slug]/page.tsx").read_text() mapping = dict(re.findall(r'"?([a-z-]+)"?: "(\w+)",', re.search(r"GUIDE_COVERS[^{]*\{(.*?)\};", slugpage, re.S).group(1))) motifs = {m.group(1): m.group(2) for m in re.finditer(r"^ ([a-zA-Z]+): \{
(.*?)^ \},", src, re.S | re.M)} norm = lambda t: re.sub(r"[^a-z0-9]+", " ", t.lower()).strip() missing, wrong = [], [] for slug, motif in mapping.items(): body = motifs.get(motif, "") t = re.search(r'teaches: "((?:[^"\]|\.)*)"', body) if not t: missing.append(motif); continue idea = norm(t.group(1).replace("\u2013", "-").replace("\u2014", "-")) # `etiquette:` and `weather:` are UNQUOTED keys in guide-content.tsx, so # the quoted pattern found nothing for them and the `if guide` guard below # silently skipped two of the eleven covers — the check reported PASS on a # set it had never looked at. guide = re.search(rf'"?{slug}"?: \[(.*?)
 \],', content, re.S) if guide and norm(guide.group(1)).find(idea) < 0: wrong.append((motif, idea[:40])) check("every guide-backed cover declares what it teaches", not missing, str(missing)) unreadable = [s for s in mapping if not re.search(rf'"?{s}"?: \[', content)] check("every guide-backed cover's body is actually readable by this check", not unreadable, str(unreadable) + " — a skipped cover reports PASS having checked nothing") check("every declared idea appears in its own guide's text", not wrong, str(wrong)) # the incentives page exists to avoid quoting amounts, so its cover must not # a currency mark means text that RENDERS as one, not a JS template literal rendered_text = lambda body: re.findall(r'text="([^"]*)"', body) check("the incentives cover shows no currency mark", not any("$" in t for t in rendered_text(motifs.get("paperwork", ""))), str(rendered_text(motifs.get("paperwork", "")))) # and the cost cover must still print no figure check("the cost cover prints no price", not re.search(r'text="[^"]*\d', motifs.get("clock", ""))) # 2. blk = re.search(r"^ connectors: \{.*?^ \},", src, re.S | re.M).group(0) plugs = {k: (float(x), float(rr)) for x, rr, k in # Decimals allowed: these are millimetres scaled into cover units, and # pinning them to integers is how a corrected 21.25 silently stopped # parsing and took the whole connectors block with it. re.findall(r'<Plug x=\{([\d.]+)\} y=\{[\d.]+\} r=\{([\d.]+)\} kind="(\w+)"', blk)} labels = {t: float(x) for x, t in re.findall(r'<Label x=\{(\d+)\} y=\{\d+\} text="(CCS1|NACS)"', blk)} check("CCS1 drawn larger than NACS", plugs["ccs1"][1] > plugs["nacs"][1], f"r {plugs['ccs1'][1]:.0f} vs {plugs['nacs'][1]:.0f}") check("CCS1 on the left, as on the cabinet", plugs["ccs1"][0] < plugs["nacs"][0]) check("each label sits on its own plug", abs(labels["CCS1"] - plugs["ccs1"][0]) < 2 and abs(labels["NACS"] - plugs["nacs"][0]) < 2) # 3. band: the 20/80 ticks must sit on the cell's actual fill edges # Trailing props are allowed — this check is here to verify the NUMBERS the # ticks derive from, not to freeze the element's styling. cell = re.search(r'<Cell x=\{(\d+)\} y=\{\d+\} w=\{(\d+)\} h=\{\d+\} from=\{([\d.]+)\} to=\{([\d.]+)\}[^/]*/>', src) # Guarded: this regex is how the tick positions get verified at all, so if the # call is ever reformatted onto several lines the run must FAIL and say why, # not raise a TypeError three lines further down. check("the band cover still declares a one-line Cell the ticks derive from", cell is not None, "keep <Cell .../> on one line, in this prop order") cxx, w, frm, to = (float(cell[1]), float(cell[2]), float(cell[3]), float(cell[4])) if cell else (0, 0, 0, 0) ticks = sorted(float(x) for x in re.findall(r'\{ x: (\d+), t: "(?:20|80)" \}', src)) want = sorted([cxx - w/2 + frm*w, cxx - w/2 + to*w]) check("band ticks on the real fill edges", all(abs(a-b) < 1 for a, b in zip(ticks, want)), f"{ticks} vs {[round(v,1) for v in want]}") # ...and that the RECTANGLE agrees with them. The line above compares the tick # to the same arithmetic the tick was written from, so it would pass happily # while Cell drew the fill somewhere else entirely — which it did, by 2.4 # units, until the fraction was made to map across the full width. cell_fn = re.search(r"function Cell\(.*?
\}
", src, re.S).group(0) check("the band's lit rectangle starts where its tick says it does", "const fx = (f: number) => l + w * f;" in cell_fn and "x={fx(from)}" in cell_fn, "the inset inner width put the drawn edge 2.4 units off the mark beside it") # 4. climate: fills must equal the shared temperature constants math_src = pathlib.Path("lib/charging-math.ts").read_text() motifs_all_early = {m.group(1): m.group(2) for m in re.finditer(r"^ ([a-zA-Z]+): \{
(.*?)^ \},", src, re.S | re.M)} TEMPS = re.findall(r'label: "([^"]+)"', math_src)[:3] cold = float(re.search(r'cold: \{[^}]*factor: ([\d.]+)', math_src)[1]) hot = float(re.search(r'hot: \{[^}]*factor: ([\d.]+)', math_src)[1]) # All THREE, now. The cover used to draw cold and hot only, which left a 62% # bar beside an 88% bar and no visible reference for either to be a share of. mild = float(re.search(r'mild: \{[^}]*factor: ([\d.]+)', math_src)[1]) climate_body = motifs_all_early.get("climate", "") missing_t = [k for k in ("cold", "mild", "hot") if f"TEMPERATURE_FACTORS.{k}" not in climate_body] check("climate shows all three temperature factors", not missing_t, f"missing {missing_t}; cold {cold}, mild {mild}, hot {hot}") check("climate's fills are computed from the factor, not typed", "f.factor" in climate_body and "* f.factor" in climate_body, "the bar height must be the factor, so the picture cannot drift from the arithmetic") check("climate prints the real temperatures the factors carry", "f.label" in climate_body, f"charging-math labels them {TEMPS}") # 5. curve: the plotted path must match min(avg vehicle curve, STATION_KW) ev = pathlib.Path("lib/ev-models.ts").read_text() curves = [{int(a): int(b) for a, b in re.findall(r"soc:(\d+),kw:(\d+)", g)} for g in re.findall(r"curve: \[(.*?)\]", ev, re.S)] STATION = int(re.search(r"STATION_KW = (\d+)", math_src)[1]) delivered = lambda soc: sum(min(interp(c, soc), STATION) for c in curves)/len(curves) vals = [(s, delivered(s)) for s in range(0, 101, 2)] pk_soc, pk = max(vals, key=lambda t: t[1]) check("curve peaks while the battery is low", pk_soc <= 25, f"peak {pk:.0f} kW at {pk_soc}%") check("curve tapers hard by 80%", delivered(80) < 0.45 * pk, f"{delivered(80):.0f} kW vs peak {pk:.0f}") check("curve is derived, not hand-drawn", "const CURVE_PLOT" in src and "evModels" in src) # ── the covers use the SHARED primitives, not a second local set ────── check("no local car or charger survives in the covers", "function CarSide(" not in src and "function Unit(" not in src) check("the covers import the shared primitives", 'from "@/components/illustration/primitives"' in src) # ── every element stands on the same ground line, by construction ────── prim = pathlib.Path("components/illustration/primitives.tsx").read_text() # CarSVG: wheels cy=53.5 r=9.6 in a 0 0 200 70 box m = re.search(r'cy=\{([\d.]+)\} r="([\d.]+)" fill=\{ILLO\.tyre\}', prim) wcy, wr = float(m[1]), float(m[2]) car_foot = (wcy + wr) / 70 declared = float(re.search(r"foot: ([\d.]+) / 70", src)[1]) / 70 check("the Car helper's foot matches CarSVG's real tyre contact", abs(car_foot - declared) < 0.002, f"{car_foot:.4f} vs declared {declared:.4f}") # ChargerSVG: contact ellipse cy in a 0 0 48 88 box ccy = float(re.search(r'<ellipse cx="24" cy="([\d.]+)"', prim)[1]) declared_u = float(re.search(r"foot: ([\d.]+) / 88", src)[1]) check("the Charger helper's foot matches ChargerSVG's contact shadow", abs(ccy - declared_u) < 0.01, f"{ccy} vs declared {declared_u}") # ── every cable hangs under gravity ─────────────────────────────────── hol_cx, hol_cy = (float(v) for v in re.search(r'<circle cx="(\d+)" cy="(\d+)" r="7.4" fill=\{ILLO\.shadow\}', prim).groups()) port_cx, port_cy = (float(v) for v in re.search(r'<circle cx="(\d+)" cy="(\d+)" r="2" fill=\{ILLO\.live\}', prim).groups()) FOOT_U = float(re.search(r"foot: ([\d.]+) / 88", src)[1]) FOOT_C = float(re.search(r"foot: ([\d.]+) / 70", src)[1]) calls = re.findall( r"sagPath\(holsterAt\((\d+), (\d+)\), portAt\((\d+), (\d+)(, true)?\)", src) calls = re.findall(r"sagPath\((\d+), (\d+), (\d+), (\d+), (\d+)\)", src) anchored = re.findall( r"sagPath\(holsterAt\((\d+), (\d+)\), portAt\((\d+), (\d+)(, true)?\), (\d+)\)", src) bad = [] for hx, hh, cx_, cw, flip, sag in anchored: a = holster(float(hx), float(hh)) b = car_port(float(cx_), float(cw), bool(flip)) if lowest(a[0], a[1], b[0], b[1], float(sag)) <= max(a[1], b[1]) + 0.5: bad.append((hx, cx_)) check("every cable sags BELOW both of its endpoints", not bad, "a cable that bulges upward is a suspension span, not a hanging cable") # ── cables begin at a holster and end at a port ─────────────────────── # # This check existed, caught exactly this bug, and I deleted it along with the # old primitives — after which every live cable drifted 40-58 units off both # anchors again. The anchors are read from primitives.tsx rather than restated # here, so the two cannot diverge. check("every live cable is anchored, not typed", len(anchored) == src.count("live animated"), f"{len(anchored)} anchored of {src.count('live animated')} live cables") off = [] for hx, hh, cx_, cw, flip in calls: a = holster(float(hx), float(hh)) b = car_port(float(cx_), float(cw), bool(flip)) if a[1] < 100 or b[1] < 100: # both must sit low on the scene off.append((hx, cx_)) check("cable anchors land on the hardware, not in the sky", not off, str(off)) # no <Cable> may simply stop in open air # ── A HAND-TYPED LEAD MUST END ON SOMETHING ────────────────────────── # # The only rule here used to be that the path string contained a "C", which # the NACS lead on the connectors cover satisfied while ending fifteen units # above the board it was supposed to plug into and eight units past the end # of it. "Has a curve in it" is not "is attached to anything". # # Anchored leads go through sagPath(holsterAt(...), portAt(...)) and are # checked above. Everything else is typed, and a typed lead now has to name # the thing it lands on: leadPath([x,y], [x, BOARD_Y]) reads the board's own # top edge, so moving the board moves both leads with it. loose = re.findall(r'<Cable d="(M[^"]+)"', src) check("no cable is left with a typed, unterminated path", not loose, f"{len(loose)} hand-typed cable path(s): {loose}. Use sagPath() between " "two anchors, or leadPath() to a named landing like BOARD_Y") leads = re.findall(r"leadPath\(\[([\d.]+), ([\d.]+)\], \[([\w.\[\]]+), ([\w.\[\]]+)\]\)", src) check("every typed lead lands on a named edge, not a number", len(leads) == src.count("leadPath(["), "a lead whose end y is a literal is a lead that stops agreeing with the " "hardware the moment the hardware moves") for x0, y0, x1, land in leads: # The landing must be a NAME. A literal is a number that stops agreeing # with the hardware the moment the hardware moves, which is how the NACS # relief ended up fifteen units off its own board. check(f"the lead from ({x0},{y0}) lands on a named point", not land.replace(".", "").isdigit(), f"ends at the literal {land}") # a lead must reach the nearer flank, not cross the whole car crossing = [] for hx, hh, cx_, cw, flip, sag in anchored: hxv, cxv = float(hx), float(cx_) px = car_port(cxv, float(cw), bool(flip))[0] on_left = px < cxv if (hxv < cxv) != on_left: crossing.append((hx, cx_)) check("every lead reaches the flank facing the charger", not crossing, "otherwise the cable is drawn straight through the bodywork") # ── motion: entrance plays once, ambient loops, and the budget is real ── # # The rule here used to be "there is exactly one looping class in the whole # file". That was a proxy for "nothing pulls the eye while somebody reads", # and it bought the quiet honestly — but it bought it at the price of # seventeen of twenty-one covers being a frozen image 1.6 seconds after load. # A masthead that finishes moving before the reader has finished arriving is # a still picture with a wind-up on it. # # The rule now says what it always meant, and says it PER COVER, which is the # only scope a reader ever has: one cover, on one page, at one time. motifs_all = {m.group(1): m.group(2) for m in re.finditer(r"^ ([a-zA-Z]+): \{
(.*?)^ \},", src, re.S | re.M)} check("the cover registry still parses", len(motifs_all) >= 21, f"{len(motifs_all)} motifs") css = pathlib.Path("app/globals.css").read_text() ENTRANCE = {"hc-rise", "hc-draw", "hc-fill", "hc-pop"} AMBIENT = {"hc-flow", "hc-standby", "hc-breathe", "hc-drift", "hc-meter"} # the parallax frame: layout and compositing, not animation FRAME = {"hc-cover", "hc-plane", "hc-atmo", "hc-sheen"} # Not animations: a hover changing colour or nudging an icon has no timeline # to play, and writing it as a keyframe would make it uninterruptible. These # exist so no component reaches for Tailwind's transition-* utilities, which # compile to cubic-bezier(0.4,0,0.2,1) at BUILD time — Material's curve, in a # string no author ever types and no grep of the source can see. TRANSITION = {"hc-move", "hc-tint"} # The site chrome. The nav and the footer render on all 60 routes and were the # only framer-motion in the shared shell, which put a 171 kB chunk on every # route's critical path — emitted three times over — to run entrance slides and # hover scales. These replace it. hc-reveal and hc-sheet exist because an EXIT # animation is the one thing CSS cannot do to an element React has unmounted: # both surfaces stay mounted and animate on a data attribute instead. SHELL = {"hc-drop", "hc-press", "hc-reveal", "hc-sheet"} # The full name, not the first hyphenated word: the old pattern read # `.hc-lift-in {` as `hc-lift` and then failed to match, so a whole family of # modifier classes was invisible to the rule that exists to see all of them. declared = {c for c in re.findall(r"^\.(hc-[a-z-]+?)(?::[a-z-]+)?[\s,]*\{", css, re.M)} # Modifiers (-sm, -in, -grow) belong to the class they modify and are checked # with it rather than being listed separately. MODIFIER = {"hc-press-sm", "hc-lift-in", "hc-grow", "hc-grow-sm", "hc-nudge", "hc-raise", "hc-raise-grow"} declared -= FRAME | MODIFIER check("the hc-* animation vocabulary is exactly what globals.css declares", declared == ENTRANCE | AMBIENT | TRANSITION | SHELL, f"css has {sorted(declared)}, script expects {sorted(ENTRANCE | AMBIENT | TRANSITION | SHELL)}") for c in sorted(SHELL): r = rule_of(css, c) check(f"chrome '{c}' costs no JavaScript", "animation" in r or "transition" in r) check("the drawer can animate OUT, not just in", 'visibility' in rule_of(css, "hc-sheet"), "conditional rendering cannot animate an exit, which is the whole reason " "AnimatePresence was here; keeping it mounted means visibility has to do " "the work of removing it from the tab order and the a11y tree") check("an open surface is only open when it says so", '.hc-sheet[data-open="true"]' in css and '.hc-reveal[data-open="true"]' in css) for c in sorted(ENTRANCE): check(f"entrance '{c}' plays once", "infinite" not in rule(c)) check(f"entrance '{c}' settles visible under reduced motion", "backwards" in rule(c) or "forwards" in rule(c), "an entrance with no fill mode snaps back to its hidden `from` state " "and the element is invisible for good") for c in sorted(AMBIENT): check
